using System.Text.Json.Serialization;

namespace MyApp.Evals.Tests;

public sealed class EvalTestCase
{
    [JsonPropertyName("id")]
    public string Id { get; set; } = string.Empty;

    [JsonPropertyName("user_message")]
    public string UserMessage { get; set; } = string.Empty;

    [JsonPropertyName("expected_traits")]
    public List<string> ExpectedTraits { get; set; } = [];
}

using System.Text.Json;

namespace MyApp.Evals.Tests;

public static class EvalDataLoader
{
    private static readonly JsonSerializerOptions Options = new()
    {
        PropertyNameCaseInsensitive = true
    };

    public static IEnumerable<EvalTestCase> LoadGolden(string relativePath = "Quality/golden.json")
    {
        var path = Path.Combine(AppContext.BaseDirectory, relativePath);
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<List<EvalTestCase>>(json, Options)
            ?? throw new InvalidOperationException($"Failed to deserialize {path}");
    }

    public static IEnumerable<object[]> GetTestData()
    {
        return LoadGolden().Select(tc => new object[] { tc });
    }
}

using Xunit;

namespace MyApp.Evals.Tests;

public class QualityEvalTests
{
    public static IEnumerable<object[]> GoldenCases => EvalDataLoader.GetTestData();

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task EvalCase_MeetsExpectedTraits(EvalTestCase testCase)
    {
        // Arrange: send user_message to the agentic app
        var response = await InvokeAgentAsync(testCase.UserMessage);

        // Assert: verify expected traits are present in the response
        Assert.NotNull(response);
        Assert.NotEmpty(response);

        foreach (var trait in testCase.ExpectedTraits)
        {
            Assert.True(
                response.Contains(trait, StringComparison.OrdinalIgnoreCase),
                $"[{testCase.Id}] Response missing expected trait: '{trait}'");
        }
    }

    private static Task<string> InvokeAgentAsync(string userMessage)
    {
        // TODO: Replace with actual agent invocation against MyApp.AppHost
        // This stub returns the user message to allow the harness to compile and run.
        return Task.FromResult(userMessage);
    }
}

